// Writes Nafyn's OpenAPI spec to a JSON file.
//
//   bun run openapi [--out openapi/nafyn.openapi.json] [--server https://nafyn.example.com]
//
// The spec is generated by Nitro from every route's `defineRouteMeta({ openAPI })`, and only exists inside a
// running Nitro app, so this starts `nuxt dev` on a free port, fetches `/_openapi.json` and stops it again.
//
// The dev server is started with MYSQL_HOST/MYSQL_PORT pointed at nothing: the database plugin then fails
// fast (one logged "ECONNREFUSED", harmless) instead of creating or migrating tables in your real database
// just to print a document. Nothing else needs the database to serve the spec.

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

function option(name: string, fallback: string): string {
    const index = process.argv.indexOf(`--${name}`);
    return index !== -1 && process.argv[index + 1] ? process.argv[index + 1]! : fallback;
}

const out = resolve(option("out", "openapi/nafyn.openapi.json"));
// relative by default: the spec describes the API, not the machine it was generated on
const server = option("server", "/");
const TIMEOUT_MS = 180_000;

const probe = Bun.serve({ port: 0, fetch: () => new Response("") });
const port = probe.port;
probe.stop(true);

const nuxt = Bun.spawn([resolve("node_modules/.bin/nuxt"), "dev", "--port", String(port), "--no-fork"], {
    env: {
        ...process.env,
        MYSQL_HOST: "127.0.0.1",
        MYSQL_PORT: "1",
        NAFYN_ENV_CHECK: "false",
        NUXT_TELEMETRY_DISABLED: "1"
    },
    stdout: "ignore",
    stderr: "ignore"
});

async function fetchSpec(): Promise<unknown> {
    const deadline = Date.now() + TIMEOUT_MS;
    while (Date.now() < deadline) {
        if (nuxt.exitCode !== null) throw new Error(`nuxt dev exited early (code ${nuxt.exitCode}); run \`bun run dev\` to see why`);
        try {
            const response = await fetch(`http://localhost:${port}/_openapi.json`);
            if (response.ok) return await response.json();
        } catch {
            // not listening yet
        }
        await Bun.sleep(1000);
    }
    throw new Error(`no OpenAPI spec after ${TIMEOUT_MS / 1000}s`);
}

try {
    console.log(`starting nuxt dev on :${port} ...`);
    const spec = await fetchSpec() as { paths: Record<string, unknown>, servers?: unknown };
    spec.servers = [{ url: server }];

    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, JSON.stringify(spec, null, 2) + "\n");
    console.log(`wrote ${Object.keys(spec.paths).length} paths to ${out}`);
} catch (error) {
    console.error((error as Error).message);
    process.exitCode = 1;
} finally {
    nuxt.kill();
}
